SELECT reservation_id AS reservationId, board_id AS boardId, budget_id AS budgetId, effect_key AS effectKey,
       offer_hash AS offerHash, gross, status FROM city_reward_reservation
WHERE board_id=#{boardId} AND effect_key=#{effectKey}
